const body = $input.first().json.body;
const year = new Date().getFullYear();
const seq = String(Math.floor(Math.random() * 9000) + 1000);
const reference = 'TS-' + year + '-' + seq;

const POSTGREST = 'https://postgrest-production-7960.up.railway.app';
const JWT = 'REDACTED_POSTGREST_JWT';

const payload = {
  reference,
  source: 'intake',
  status: 'reasoning',
  title: body.title || body.description || 'Untitled',
  description: body.description || '',
  ticket_type: body.ticket_type || 'purchase',
  submitted_by: body.submitted_by || '',
  submitted_by_email: body.submitted_by_email || '',
  supplier_name: body.supplier_name || '',
  value_eur: parseFloat(body.value_eur || body.amount || 0),
  category: body.category || 'other',
  branch_id: body.branch_id || null
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/tickets',
  headers: {
    'Authorization': 'Bearer ' + JWT,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify(payload),
  returnFullResponse: true
});

const ticket = response.body[0] || response.body;

return [{ json: { ticket, reference, body } }];

const intake = $node['Intake Form Submitted'].json.body;
const supplier = $node['Fetch Supplier Context'].json;
const contract = $node['Fetch Contract Context'].json;
const budget = $node['Fetch Budget Context'].json;
const manager = $node['Fetch Responsible Manager'].json;

const ANTHROPIC_KEY = $env.ANTHROPIC_API_KEY;

const prompt = `Reason on this procurement intake request and return a disposition.

REQUEST:
${JSON.stringify(intake)}

SIGNAL 1 - CONTRACT:
${JSON.stringify(contract)}

SIGNAL 2 - BUDGET:
${JSON.stringify(budget)}

SIGNAL 3 - SUPPLIER:
${JSON.stringify(supplier)}

SIGNAL 4 - REQUEST: ${intake.ticket_type || 'purchase'} for EUR ${intake.value_eur || intake.amount || 0} by ${intake.submitted_by || 'unknown'}

SIGNAL 5 - POLICY:
- CATALOG ITEMS (description contains SKU codes like APPMBP14M3PRO, GHENT, MS365E3 etc): These are pre-approved catalog items with contracts already on file. If budget is available, ALWAYS return auto_execute with confidence >= 0.95. Do not route catalog items to one_touch under any circumstance unless the budget bucket is completely exhausted.
- Auto-execute if all 5 signals green and confidence >= 0.85.
- One-touch if any signal uncertain or confidence < 0.85.
- Escalate if amount > EUR 100000 OR compliance blocker detected.

Return ONLY valid JSON (no markdown, no explanation outside JSON):
{
  "disposition": "auto_execute" or "one_touch" or "escalate",
  "confidence": 0.0 to 1.0,
  "reasoning": "string — explain each of the 5 signals",
  "recommendation": "string — one sentence action",
  "brief": "string — one sentence for the submitter",
  "action_taken": "string",
  "supplier_email_subject": "string or null",
  "supplier_email_body": "string or null",
  "requires_order": true or false,
  "signals": [
    { "signal": "contract",    "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "policy",      "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "supplier",    "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "request",     "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "consumption", "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." }
  ]
}`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': ANTHROPIC_KEY,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 1500,
    messages: [{ role: 'user', content: prompt }]
  })
});

const text = response.content[0].text;
// Strip markdown fences if Claude wraps in them
const clean = text.replace(/^```json
?/,'').replace(/
?```$/,'').trim();
const result = JSON.parse(clean);

return [{ json: result }];

const result = $input.first().json;
const ticketId = $node['Create Ticket in PostgREST'].json.ticket?.id;

const JWT = 'REDACTED_POSTGREST_JWT';
const POSTGREST = 'https://postgrest-production-7960.up.railway.app';

const decision = await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/decisions',
  headers: {
    'Authorization': 'Bearer ' + JWT,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify({
    ticket_id: ticketId,
    disposition: result.disposition,
    confidence: result.confidence,
    reasoning: result.reasoning,
    recommendation: result.recommendation,
    brief: result.brief,
    model_used: 'claude-sonnet-4-6'
  })
});

return [{ json: { ...result, decision_id: decision[0]?.id, ticket_id: ticketId } }];

const intake = $node['Intake Form Submitted'].json.body;
const result = $node['Write Decision to PostgREST'].json;
const supplier = $node['Fetch Supplier Context'].json;
const contract = $node['Fetch Contract Context'].json;
const manager = $node['Fetch Responsible Manager'].json;

const JWT = 'REDACTED_POSTGREST_JWT';
const POSTGREST = 'https://postgrest-production-7960.up.railway.app';

const po = await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/rpc/approve_and_commit',
  headers: {
    'Authorization': 'Bearer ' + JWT,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify({
    p_ticket_id: result.ticket_id,
    p_branch_id: intake.branch_id,
    p_branch_code: intake.branch_code || 'HQ',
    p_cost_center_id: null,
    p_category: intake.category || 'other',
    p_period: new Date().getFullYear() + '-Q' + Math.ceil((new Date().getMonth()+1)/3),
    p_supplier_id: supplier[0]?.id || null,
    p_contract_id: contract[0]?.id || null,
    p_description: intake.title || intake.description,
    p_amount: parseFloat(intake.value_eur || intake.amount || 0),
    p_currency: 'EUR',
    p_amount_eur: parseFloat(intake.value_eur || intake.amount || 0),
    p_raised_by: manager[0]?.id || null,
    p_expected_delivery: new Date(Date.now() + 14*24*60*60*1000).toISOString().split('T')[0],
    p_line_items: null
  })
});

return [{ json: { po: po[0] || po, ticket_id: result.ticket_id } }];

const ticketId = $node['Write Decision to PostgREST'].json.ticket_id;
const result = $node['Write Decision to PostgREST'].json;

const JWT = 'REDACTED_POSTGREST_JWT';

await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://postgrest-production-7960.up.railway.app/tickets?id=eq.' + ticketId,
