    status: 'pending_review',
    recommendation: result.recommendation,
    brief: result.brief,
    confidence: result.confidence
  })
});

return [{ json: { ticket_id: ticketId, status: 'pending_review' } }];

const ticketId = $node['Write Decision to PostgREST'].json.ticket_id;
const result = $node['Write Decision to PostgREST'].json;

const JWT = 'REDACTED_POSTGREST_JWT';

await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://postgrest-production-7960.up.railway.app/tickets?id=eq.' + ticketId,
  headers: {
    'Authorization': 'Bearer ' + JWT,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify({
    status: 'escalated',
    recommendation: result.recommendation,
    brief: result.brief,
    confidence: result.confidence
  })
});

return [{ json: { ticket_id: ticketId, status: 'escalated' } }];

const intake = $node['Intake Form Submitted'].json.body;
const po = $input.first().json.po;
const ticketId = $input.first().json.ticket_id;
const result = $node['Write Decision to PostgREST'].json;
const supplier = $node['Fetch Supplier Context'].json;

const JWT = 'REDACTED_POSTGREST_JWT';

// Fetch branch for PO header
const branches = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://postgrest-production-7960.up.railway.app/branches?id=eq.' + intake.branch_id + '&select=id,name,legal_name,street_address,city_zip,vat_number,po_email,currency',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
});
const branch = branches[0] || {};

// Close ticket
await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://postgrest-production-7960.up.railway.app/tickets?id=eq.' + ticketId,
  headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    status: 'auto_executed',
    recommendation: result.recommendation,
    brief: result.brief,
    confidence: result.confidence,
    po_number: po?.po_number
  })
});

return [{ json: { po, branch, intake, supplier: supplier[0] || {}, ticket_id: ticketId } }];

