const result = $input.first().json;
const decisionId = result.decision_id;

const JWT = 'REDACTED_POSTGREST_JWT';
const POSTGREST = 'https://postgrest-production-7960.up.railway.app';

if (!decisionId) {
  console.log('No decision_id — skipping trace write');
  return [{ json: result }];
}

// Parse the signals from Claude's output
const signals = result.signals || [];

if (signals.length === 0) {
  // Build signals from Claude result fields if not structured
  const fallback = [
    { signal: 'contract',    value: result.contract_signal    || 'checked', weight: result.contract_weight    || 0.8,  green: result.contract_green    ?? true,  notes: result.contract_notes    || '' },
    { signal: 'policy',      value: result.budget_signal      || 'checked', weight: result.budget_weight      || 0.8,  green: result.budget_green      ?? true,  notes: result.budget_notes      || '' },
    { signal: 'supplier',    value: result.supplier_signal    || 'checked', weight: result.supplier_weight    || 0.8,  green: result.supplier_green    ?? true,  notes: result.supplier_notes    || '' },
    { signal: 'request',     value: result.request_signal     || 'checked', weight: result.request_weight     || 0.8,  green: result.request_green     ?? true,  notes: result.request_notes     || '' },
    { signal: 'consumption', value: result.consumption_signal || 'checked', weight: result.consumption_weight || 0.8,  green: result.consumption_green ?? true,  notes: result.consumption_notes || '' },
  ];
  signals.push(...fallback);
}

const rows = signals.slice(0, 5).map(s => ({
  decision_id: decisionId,
  signal:      s.signal,
  value:       typeof s.value === 'object' ? JSON.stringify(s.value) : String(s.value || ''),
  weight:      Math.min(Math.max(parseFloat(s.weight) || 0.8, 0), 0.9999),
  green:       s.green === true || s.green === 'true',
  notes:       s.notes || ''
}));

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: POSTGREST + '/trace_log',
    headers: {
      'Authorization': 'Bearer ' + JWT,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify(rows)
  });
} catch(e) {
  // Non-fatal — trace failure must not block routing
  console.error('Trace write failed (non-fatal):', e.message);
}

return [{ json: result }];
